def tree(node_label, branches=None):
    if branches is None:
        branches = []
    # A tree is a list: [label, branch1, branch2, ...]
    return [node_label] + list(branches)

def label(t):
    return t[0]

def branches(t):
    return t[1:]

def is_leaf(t):
    return len(branches(t)) == 0

# Example tree from the prompt

t = tree(3, [
    tree(1),
    tree(2, [tree(1), tree(1)])
])

print(t)
print(label(t))
print([label(b) for b in branches(t)])
print(is_leaf(t), is_leaf(branches(t)[0]))

def count_leaves(t):
    if is_leaf(t):
        return 1
    return sum(count_leaves(b) for b in branches(t))
print(count_leaves(t))

def tree_map(f, t):
    return tree(
        f(label(t)),
        [tree_map(f, b) for b in branches(t)]
    )

squared = tree_map(lambda x: x * x, t)
plus_one = tree_map(lambda x: x + 1, t)

print(label(plus_one))
print(squared)
print(plus_one)

def fib_tree(n):
    if n <= 1:
        return tree(n)
    left = fib_tree(n - 1)
    right = fib_tree(n - 2)
    return tree(label(left) + label(right), [left, right])

ft5 = fib_tree(5)
print(label(ft5))
print(count_leaves(ft5))
